// @FIGURE_CODE_BEGIN
/* ───────────────────────── geometry & palette ───────────────────────── */
var PAL = { pale: '#e8e8e8', dark: '#a8a8a8', white: '#ffffff', accent: '#e8720c', bad: '#d62728' };
var FIG_W = 640, FIG_H = 150;
var STRIP_X = 22, STRIP_W = 596, CY = 58, CH = 40;
var ANNOY = 12, ARROWY = 30, LABELY = 44, BY = 106, CAPY = 136;

var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, FIG_W, FIG_H);

var hatch = figDraw.pattern(7, 7, function (add) {
  add.rect(7, 7).fill('#ffe3e3');
  add.line(0, 7, 7, 0).stroke({ color: PAL.bad, width: 1.4 });
});

var gCells = figDraw.group(), gBars = figDraw.group(), gBraces = figDraw.group(),
  gArrow = figDraw.group(), gLabels = figDraw.group(), gAnno = figDraw.group();

/* ───────────────────────── drawing helpers ───────────────────────── */
function drawBrace(g, x0, x1, y) {
  var w = x1 - x0;
  if (w < 10) return;
  var d = Math.min(8, w / 4), mid = (x0 + x1) / 2;
  var p = 'M' + x0 + ' ' + y +
    ' Q' + x0 + ' ' + (y + d) + ' ' + (x0 + d) + ' ' + (y + d) +
    ' L' + (mid - d) + ' ' + (y + d) +
    ' Q' + mid + ' ' + (y + d) + ' ' + mid + ' ' + (y + 2 * d) +
    ' Q' + mid + ' ' + (y + d) + ' ' + (mid + d) + ' ' + (y + d) +
    ' L' + (x1 - d) + ' ' + (y + d) +
    ' Q' + x1 + ' ' + (y + d) + ' ' + x1 + ' ' + y;
  g.path(p).fill('none').stroke({ color: '#000', width: 1.2, linecap: 'round', linejoin: 'round' });
}

function arrowHead(g, x, y, dx, dy, size, color) {
  var len = Math.sqrt(dx * dx + dy * dy) || 1; dx /= len; dy /= len;
  var px = -dy, py = dx;
  var pts = [
    x + ',' + y,
    (x - dx * size + px * size * 0.55) + ',' + (y - dy * size + py * size * 0.55),
    (x - dx * size - px * size * 0.55) + ',' + (y - dy * size - py * size * 0.55)
  ].join(' ');
  g.polygon(pts).fill(color);
}

function swapArc(g, xa, xb, color) {
  var y0 = CY - 3, mid = (xa + xb) / 2;
  var apex = Math.max(24, y0 - (10 + Math.abs(xb - xa) * 0.22));
  g.path('M' + xa + ' ' + y0 + ' Q' + mid + ' ' + apex + ' ' + xb + ' ' + y0)
    .fill('none').stroke({ color: color, width: 1.8 });
  arrowHead(g, xa, y0, -(mid - xa), -(apex - y0), 6, color);
  arrowHead(g, xb, y0, (xb - mid), (y0 - apex), 6, color);
}

function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  return t;
}

function regionBlurb(region, bad) {
  var m = {
    le: 'This cell lies in A[p..i]: the loop has already proved its value is ≤ the pivot x. The i bar is the frontier of this known-small region.',
    gt: 'This cell lies in A[i+1..j-1]: it has been examined and found greater than x, so it stays put and the region simply grows to the right.',
    un: 'This cell lies in A[j..r-1]: it has never been looked at. Each iteration examines exactly one of these cells.',
    pivot: 'This is the pivot x = A[r]. It sits out of the way until the loop ends, then one final swap drops it on the seam between the two regions.'
  };
  return (bad ? 'INVARIANT VIOLATED here. ' : '') + m[region];
}

/* ───────────────────────── the renderer ───────────────────────── */
function render(st) {
  [gCells, gBars, gBraces, gArrow, gLabels, gAnno].forEach(function (g) { g.clear(); });
  var n = st.n, cw = STRIP_W / n;
  var pivotCell = (st.pivotCell == null ? st.r : st.pivotCell);
  function ex(k) { return STRIP_X + k * cw; }
  function cx(k) { return STRIP_X + (k + 0.5) * cw; }

  for (var k = 0; k < n; k++) {
    var region, fill;
    if (k === pivotCell) { region = 'pivot'; fill = PAL.white; }
    else if (k <= st.i) { region = 'le'; fill = PAL.pale; }
    else if (k < st.j) { region = 'gt'; fill = PAL.dark; }
    else { region = 'un'; fill = PAL.white; }
    var bad = !!(st.violations && st.violations.indexOf(k) >= 0);
    var cell = gCells.rect(cw, CH).move(ex(k), CY)
      .fill(bad ? hatch : fill).stroke({ color: '#000', width: 1 });
    cell.css('cursor', 'pointer');
    (function (idx, reg, isBad) {
      var names = { le: '≤ x (known small)', gt: '> x (known large)', un: 'unrestricted (not yet examined)', pivot: 'the pivot x' };
      var val = st.values ? String(st.values[idx]) : null;
      cell.on('mousemove', function (e) {
        showTooltip('A[' + idx + ']' + (val ? ' = ' + val : '') + ' — ' + names[reg] + (isBad ? '  ⚠ violates the invariant' : ''), e);
      }).on('mouseleave', hideTooltip)
        .on('click', function () { showPopup('Cell A[' + idx + ']', regionBlurb(reg, isBad)); });
    })(k, region, bad);

    if (st.values) {
      halo(gCells.text(String(st.values[k]))
        .font({ family: 'Georgia, serif', size: Math.min(17, cw * 0.42), anchor: 'middle' })
        .fill('#111')).center(cx(k), CY + CH / 2);
    } else if (k === pivotCell && st.pivotText) {
      gCells.text(st.pivotText)
        .font({ family: 'Georgia, serif', size: Math.min(20, cw * 0.55), anchor: 'middle', style: 'italic' })
        .fill('#111').center(cx(k), CY + CH / 2);
    }
  }

  // heavy boundary bars
  var bw = Math.max(3, Math.min(8, cw * 0.2));
  var bars = st.bars || [
    { edge: st.i + 1, label: 'The i bar', tip: 'i = ' + st.i + ' — everything left of this bar is known ≤ x. i is the frontier of what is known small.' },
    { edge: st.j, label: 'The j bar', tip: 'j = ' + st.j + ' — everything left of this bar has been examined. j is the frontier of what has been looked at at all.' },
    { edge: pivotCell, label: 'The pivot boundary', tip: 'The pivot x = A[' + pivotCell + '] waits here, outside all three regions, until the loop ends.' }
  ];
  bars.forEach(function (b) {
    var bx = Math.min(Math.max(ex(b.edge), STRIP_X + bw / 2), STRIP_X + STRIP_W - bw / 2);
    var rct = gBars.rect(bw, CH + 8).move(bx - bw / 2, CY - 4).fill('#000');
    rct.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(b.tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup(b.label, b.tip); });
  });

  // braces + captions
  var braces = st.braces || [
    { a: st.p, b: st.i, t: '≤ x', it: true },
    { a: st.i + 1, b: Math.min(st.j - 1, pivotCell - 1), t: '> x', it: true },
    { a: st.j, b: pivotCell - 1, t: 'unrestricted', it: false }
  ];
  braces.forEach(function (br) {
    if (br.b < br.a || br.a < 0 || br.b > n - 1) return;
    var x0 = ex(br.a) + 1, x1 = ex(br.b + 1) - 1;
    drawBrace(gBraces, x0, x1, BY);
    var cap = gBraces.text(br.t)
      .font({ family: 'Georgia, serif', size: 15, anchor: 'middle', style: br.it ? 'italic' : 'normal' })
      .fill('#000');
    halo(cap).center((x0 + x1) / 2, CAPY);
  });

  // motion indicators
  if (st.moveJ) {
    var xa = Math.max(STRIP_X, ex(st.moveJ[0])), xb = Math.min(STRIP_X + STRIP_W, ex(st.moveJ[1]));
    gArrow.line(xa, ARROWY, xb - 6, ARROWY).stroke({ color: PAL.accent, width: 1.8 });
    arrowHead(gArrow, xb, ARROWY, 1, 0, 6, PAL.accent);
  }
  if (st.swapPair) {
    swapArc(gArrow, cx(st.swapPair[0]), cx(st.swapPair[1]), PAL.accent);
  }
  if (st.compared != null && st.compared >= 0 && st.compared < n) {
    gArrow.rect(cw - 4, CH - 4).move(ex(st.compared) + 2, CY + 2)
      .fill('none').stroke({ color: PAL.accent, width: 2.5, linejoin: 'round' });
  }

  // index labels (drawn last, haloed, always readable)
  var labels = st.labels || [
    { k: st.p, t: 'p' }, { k: st.i, t: 'i' }, { k: st.j, t: 'j' }, { k: st.r, t: 'r' }
  ];
  labels.forEach(function (L) {
    var lx;
    if (L.k < 0) lx = STRIP_X - 7;
    else if (L.k > n - 1) lx = STRIP_X + STRIP_W + 7;
    else lx = cx(L.k);
    lx = Math.max(9, Math.min(FIG_W - 9, lx));
    halo(gLabels.text(L.t)
      .font({ family: 'Georgia, serif', size: 17, style: 'italic', anchor: 'middle' })
      .fill('#000')).center(lx, LABELY);
  });

  if (st.note) {
    var txt = st.note.length > 104 ? st.note.slice(0, 101) + '…' : st.note;
    halo(gAnno.text(txt)
      .font({ family: 'Helvetica, Arial, sans-serif', size: 10.5, anchor: 'middle' })
      .fill('#333')).center(FIG_W / 2, ANNOY);
  }
}

/* ───────────────────────── schematic (default) view ───────────────────────── */
var viewMode = 'schematic';
var schematic = { branch: 'skip', phase: 'idle' };

function renderSchematic() {
  var st = {
    n: 16, p: 0, r: 15, i: 3, j: 10, pivotCell: 15,
    values: null, pivotText: 'x', compared: null, swapPair: null,
    violations: [], note: null, moveJ: null
  };
  if (schematic.phase === 'before') {
    st.compared = 10;
    if (schematic.branch === 'swap') {
      st.swapPair = [4, 10];
      st.note = 'A[j] ≤ x — the ≤ x region must grow, so i++ and swap A[i] with A[j]: both bars advance.';
    } else {
      st.moveJ = [10, 11];
      st.note = 'A[j] > x — nothing is exchanged: j advances alone and the > x region swallows the cell.';
    }
  } else if (schematic.phase === 'after') {
    if (schematic.branch === 'swap') {
      st.i = 4; st.j = 11;
      st.note = 'Invariant restored: ≤ x grew by one cell, the evicted > x value landed at the end of the > x run.';
    } else {
      st.i = 3; st.j = 11;
      st.note = 'Invariant restored: > x grew by one cell, i and the pale region never moved.';
    }
  }
  render(st);
  document.getElementById('applyIterBtn').textContent =
    (schematic.phase === 'after') ? '◂ Reset iteration' : 'Apply this iteration ▸';
}

/* ───────────────────────── sandboxed trace runner ───────────────────────── */
var RUNNER_BODY = `
function runPartition(code, arr){
  var A = arr.slice();
  var p = 0, r = A.length - 1;
  var I = p - 1, J = p;
  var frames = [];
  var ops = 0, MAXOPS = 20000, MAXFRAMES = 400;
  var t0 = Date.now();
  function guard(){
    ops++;
    if (ops > MAXOPS) throw new Error('Operation cap reached (' + MAXOPS + ') - the loop never ends.');
    if (frames.length >= MAXFRAMES) throw new Error('Frame cap reached (' + MAXFRAMES + ') - too many recorded steps.');
    if (Date.now() - t0 > 1500) throw new Error('Timed out after 1.5 s - the loop probably never ends.');
  }
  function chk(k, name){
    k = Number(k);
    if (!isFinite(k) || Math.floor(k) !== k || k < 0 || k > r) throw new Error(name + '(' + k + '): index outside 0..' + r);
    return k;
  }
  function push(kind, idx, msg, cmp, swp){
    frames.push({ kind: kind, state: A.slice(), i: I, j: J, p: p, r: r, indices: idx || [], message: msg, compared: cmp || null, swap: swp || null });
  }
  function pivot(){ return A[r]; }
  function value(k){ k = chk(k, 'value'); return A[k]; }
  function lessEq(k){
    guard(); k = chk(k, 'lessEq');
    var res = A[k] <= A[r];
    push('compare', [k, r], 'compare A[' + k + '] = ' + A[k] + (res ? ' \\u2264 ' : ' > ') + 'x = ' + A[r] + '  \\u2192  ' + res, { k: k, res: res }, null);
    return res;
  }
  function swap(a, b){
    guard(); a = chk(a, 'swap'); b = chk(b, 'swap');
    var t = A[a]; A[a] = A[b]; A[b] = t;
    push('swap', [a, b], 'swap A[' + a + '] \\u2194 A[' + b + ']  \\u2192  A[' + a + ']=' + A[a] + ', A[' + b + ']=' + A[b], null, [a, b]);
  }
  function setI(k){
    guard(); k = Number(k);
    if (!isFinite(k) || Math.floor(k) !== k || k < p - 1 || k > r) throw new Error('setI(' + k + '): must be between ' + (p - 1) + ' and ' + r);
    I = k;
    push('setI', [k], 'i = ' + k + (k < p ? '  \\u2192  the \\u2264 x region is empty' : '  \\u2192  \\u2264 x region is A[' + p + '..' + k + ']'), null, null);
  }
  function setJ(k){
    guard(); k = Number(k);
    if (!isFinite(k) || Math.floor(k) !== k || k < p || k > r) throw new Error('setJ(' + k + '): must be between ' + p + ' and ' + r);
    J = k;
    push('setJ', [k], 'j = ' + k + '  \\u2192  now examining cell ' + k, null, null);
  }
  function note(t){
    if (frames.length) frames[frames.length - 1].message = String(t);
    else push('note', [], String(t), null, null);
  }
  var view = A;
  try { view = new Proxy(A, { set: function(){ throw new Error('A cannot be assigned directly - use swap(a, b).'); } }); } catch(e) {}
  var q = null;
  try {
    var factory = new Function('pivot','value','lessEq','swap','setI','setJ','note',
      '"use strict";\\n' + code + '\\nif (typeof partition !== "function") { throw new Error("No function named partition(A, p, r) was defined."); }\\nreturn partition;');
    var entry = factory(pivot, value, lessEq, swap, setI, setJ, note);
    q = entry(view, p, r);
  } catch(e){
    frames.push({ kind:'error', state: A.slice(), i: I, j: J, p: p, r: r, indices: [], message: '\\u26a0 ' + ((e && e.message) ? e.message : String(e)), compared: null, swap: null, error: true });
    return { frames: frames, q: null, error: true };
  }
  frames.push({ kind:'done', state: A.slice(), i: I, j: J, p: p, r: r, indices: [], message: 'loop finished \\u2014 partition returned q = ' + q, compared: null, swap: null, done: true, q: (typeof q === 'number' ? q : null) });
  return { frames: frames, q: (typeof q === 'number' ? q : null), error: false };
}
`;

