  ].join('\n')
};

function loadSample(which) {
  document.getElementById('partitionCode').value = SAMPLES[which] || SAMPLES.starter;
}

/* ───────────────────────── replay state ───────────────────────── */
var frames = [], fidx = -1, origArr = [], lastQ = null, finalBad = [], runState = 'idle';
var invariantOn = true, playTimer = null, playFps = 2, caseFocus = 'A[j] > x (skip branch)';

function setStatus(txt, color) {
  var el = document.getElementById('runStatus');
  el.textContent = txt; el.style.color = color || '#555';
}

function parseArr() {
  var raw = document.getElementById('partitionInput').value;
  var parts = raw.split(/[^0-9eE.+-]+/).filter(function (s) { return s.length; });
  var nums = parts.map(Number);
  if (nums.length < 2 || nums.some(function (v) { return !isFinite(v); }))
    throw new Error('Enter at least 2 numbers, comma separated.');
  return nums.slice(0, 16);
}

function frameViolations(f) {
  if (!invariantOn || !f.state) return [];
  if (f.done) return finalBad.slice();
  var x = f.state[f.r], bad = [], k;
  for (k = f.p; k <= f.i && k < f.r; k++) if (f.state[k] > x) bad.push(k);
  for (k = f.i + 1; k < f.j && k < f.r; k++) if (f.state[k] <= x) bad.push(k);
  return bad;
}

function renderFrame() {
  if (fidx < 0 || !frames.length) { renderSchematic(); return; }
  var f = frames[fidx];
  var st = {
    n: f.state.length, p: f.p, r: f.r, i: f.i, j: f.j, pivotCell: f.r,
    values: f.state, pivotText: null,
    compared: f.compared ? f.compared.k : null,
    swapPair: f.swap || null,
    violations: frameViolations(f),
    note: f.message, moveJ: null
  };
  if (f.done && typeof f.q === 'number' && f.q >= 0 && f.q <= f.r) {
    var q = f.q;
    st.i = q - 1; st.j = f.r + 1; st.pivotCell = q;
    st.braces = [{ a: f.p, b: q - 1, t: '≤ x', it: true }, { a: q + 1, b: f.r, t: '> x', it: true }];
    st.labels = [{ k: f.p, t: 'p' }, { k: q, t: 'q' }, { k: f.r, t: 'r' }];
    st.bars = [
      { edge: q, label: 'the seam', tip: 'The pivot now sits at A[' + q + '] = ' + f.state[q] + ': every cell left of it is ≤ it.' },
      { edge: q + 1, label: 'the seam', tip: 'Every cell right of the pivot is > it. q = ' + q + ' is the returned split point.' }
    ];
    st.compared = q;
    st.violations = invariantOn ? finalBad.slice() : [];
  }
  render(st);
  document.getElementById('frameCaption').textContent = f.message;
  updateCounter(); updateLog();
}

function renderCurrent() { if (viewMode === 'trace') renderFrame(); else renderSchematic(); }

function updateCounter() {
  document.getElementById('frameCount').textContent = (frames.length ? (fidx + 1) : 0) + ' of ' + frames.length;
}
function updateLog() {
  var el = document.getElementById('runLog'), out = [];
  for (var k = 0; k <= fidx && k < frames.length; k++) out.push((k + 1) + '. ' + frames[k].message);
  el.textContent = out.slice(-60).join('\n');
  el.scrollTop = el.scrollHeight;
}

/* ───────────────────────── running ───────────────────────── */
function evaluate(out) {
  finalBad = [];
  var last = out.frames[out.frames.length - 1];
  if (out.error) { runState = 'error'; setStatus(last ? last.message : '⚠ error', '#c62828'); return; }
  var A = last.state, r = A.length - 1, q = out.q, x0 = origArr[origArr.length - 1], k;
  if (typeof q !== 'number' || q < 0 || q > r || Math.floor(q) !== q) {
    runState = 'wrong'; setStatus('✘ partition() did not return a valid index', '#c62828'); return;
  }
  if (A[q] !== x0) finalBad.push(q);
  for (k = 0; k < q; k++) if (A[k] > x0) finalBad.push(k);
  for (k = q + 1; k <= r; k++) if (A[k] <= x0) finalBad.push(k);
  if (finalBad.length === 0) { runState = 'ok'; setStatus('✔ correctly partitioned — q = ' + q, '#2e7d32'); }
  else {
    runState = 'wrong';
    setStatus('✘ not partitioned: cell' + (finalBad.length > 1 ? 's' : '') + ' ' + finalBad.join(', ') + ' violate the property (hatched red)', '#c62828');
  }
}

function finishRun(out, afterFn) {
  document.getElementById('runBtn').disabled = false;
  frames = out.frames || [];
  lastQ = out.q;
  evaluate(out);
  viewMode = 'trace';
  fidx = frames.length ? 0 : -1;
  renderFrame();
  if (typeof afterFn === 'function') afterFn();
}

function runCode(afterFn) {
  stopPlay();
  var arr;
  try { arr = parseArr(); } catch (e) { setStatus('⚠ ' + e.message, '#c62828'); return; }
  origArr = arr.slice();
  var code = document.getElementById('partitionCode').value;
  setStatus('running…', '#555');
  document.getElementById('runBtn').disabled = true;
  var used = false;
  try {
    var url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
    var w = new Worker(url);
    var done = false;
    var to = setTimeout(function () {
      if (done) return; done = true; w.terminate(); URL.revokeObjectURL(url);
      finishRun({
        frames: [{
          kind: 'error', state: arr.slice(), i: -1, j: 0, p: 0, r: arr.length - 1, indices: [],
          message: '⚠ Timed out — your loop never finished.', compared: null, swap: null, error: true
        }], q: null, error: true
      }, afterFn);
    }, 2200);
    w.onmessage = function (ev) {
      if (done) return; done = true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
      finishRun(ev.data, afterFn);
    };
    w.onerror = function () {
      if (done) return; done = true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
      finishRun(mainRun(code, arr), afterFn);
    };
    used = true;
  } catch (e) { used = false; }
  if (!used) finishRun(mainRun(code, arr), afterFn);
}

/* ───────────────────────── playback ───────────────────────── */
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; }
  document.getElementById('playBtn').textContent = '▶';
}
function fFirst() { stopPlay(); if (frames.length) { viewMode = 'trace'; fidx = 0; renderFrame(); } }
function fPrev() { stopPlay(); if (frames.length && fidx > 0) { viewMode = 'trace'; fidx--; renderFrame(); } }
function fNext() { stopPlay(); if (frames.length && fidx < frames.length - 1) { viewMode = 'trace'; fidx++; renderFrame(); } }
function fPlay() {
  if (playTimer) { stopPlay(); return; }
  if (!frames.length) return;
  viewMode = 'trace';
  if (fidx >= frames.length - 1) fidx = 0;
  document.getElementById('playBtn').textContent = '⏸';
  playTimer = setInterval(function () {
    if (fidx >= frames.length - 1) { stopPlay(); return; }
    fidx++; renderFrame();
  }, 1000 / playFps);
}
function update_speed(v) {
  playFps = v;
  if (playTimer) { stopPlay(); fPlay(); }
}

/* ───────────────────────── controls ───────────────────────── */
function toggle_invariantOverlay(on) { invariantOn = on; renderCurrent(); }

function applyCase(v) {
  caseFocus = v;
  document.getElementById('caseFocusInput').value = v;
  schematic.branch = (v.indexOf('≤') >= 0) ? 'swap' : 'skip';
}

function toggle_caseFocus(v) {
  caseFocus = v;
  var wantTrue = (v.indexOf('≤') >= 0);
  if (viewMode === 'trace' && frames.length) {
    stopPlay();
    var k;
    for (k = fidx + 1; k < frames.length; k++) {
      if (frames[k].kind === 'compare' && frames[k].compared && frames[k].compared.res === wantTrue) { fidx = k; renderFrame(); return; }
    }
    for (k = 0; k < frames.length; k++) {
      if (frames[k].kind === 'compare' && frames[k].compared && frames[k].compared.res === wantTrue) { fidx = k; renderFrame(); return; }
    }
    document.getElementById('frameCaption').textContent = 'no ' + v + ' iteration in this run';
  } else {
    schematic.branch = wantTrue ? 'swap' : 'skip';
    if (schematic.phase === 'idle') schematic.phase = 'before';
    viewMode = 'schematic';
    renderSchematic();
  }
}

function trigger_applyIter() {
  if (viewMode === 'trace') { fNext(); return; }
  schematic.phase = (schematic.phase === 'after') ? 'before' : 'after';
  renderSchematic();
}

function showSchematic() {
  stopPlay();
  viewMode = 'schematic';
  schematic.phase = 'idle';
  document.getElementById('frameCaption').textContent = '';
  renderSchematic();
}

/* ───────────────────────── demo steps ───────────────────────── */
function setInv(on) {
  invariantOn = on;
  document.getElementById('invariantOverlayInput').checked = on;
}
function gotoFirstCompare() {
  for (var k = 0; k < frames.length; k++) if (frames[k].kind === 'compare') { fidx = k; renderFrame(); return; }
}
function gotoFirstViolation() {
  for (var k = 0; k < frames.length; k++) {
    if (frameViolations(frames[k]).length) { fidx = k; renderFrame(); return; }
  }
  fidx = frames.length - 1; renderFrame();
}

var demoSteps = [
  {
    t: 'Read the picture before running anything',
    n: 'The strip shows the state at the top of one iteration: pale gray cells are already known ≤ x, dark gray cells are known > x, white cells have not been looked at, and the pivot x sits alone at position r. The bars at i and j are the only things that move.',
    run: function () { stopPlay(); viewMode = 'schematic'; schematic.phase = 'idle'; applyCase('A[j] > x (skip branch)'); setInv(true); renderSchematic(); }
  },
  {
    t: 'The skip branch: A[j] > x',
    n: 'When the scanned cell is greater than the pivot, nothing is exchanged — j advances by one and the dark gray > x region simply swallows the cell. The i bar and the pale gray region are untouched. Press “Apply this iteration ▸” to watch the picture restore itself.',
    run: function () { stopPlay(); viewMode = 'schematic'; applyCase('A[j] > x (skip branch)'); schematic.phase = 'before'; setInv(true); renderSchematic(); }
  },
  {
    t: 'The swap branch: A[j] ≤ x',
    n: 'When the scanned cell is at most the pivot, the ≤ x region must grow by one cell, but that cell is currently occupied by a > x value. Incrementing i and swapping A[i] with A[j] moves the small value left and pushes the big value to the far end of the > x region — both bars advance.',
    run: function () { stopPlay(); viewMode = 'schematic'; applyCase('A[j] ≤ x (swap branch)'); schematic.phase = 'before'; setInv(true); renderSchematic(); }
  },
  {
    t: 'Write the loop yourself',
    n: 'Implement partition with lessEq, swap, setI and setJ, then replay it frame by frame. Every boundary you see move is one of your own setI/setJ calls; every recoloured cell is one of your swaps.',
    run: function () { setInv(true); loadSample('sample'); runCode(gotoFirstCompare); }
  },
  {
    t: 'Break it on purpose',
    n: 'Load the buggy version that advances the i bar without swapping the small element into place. With invariant checking on, watch a cell greater than x appear inside the pale gray region — the picture stops being true, and the final array is no longer partitioned.',
    run: function () { setInv(true); loadSample('buggy'); runCode(gotoFirstViolation); }
  },
  {
    t: 'Termination: place the pivot',
    n: 'When j reaches r the unrestricted region is empty, so the array is just ≤ x followed by > x followed by the pivot. One final swap of A[i+1] with A[r] drops the pivot exactly on the seam, and i+1 is the returned split point q.',
    run: function () { setInv(true); loadSample('sample'); runCode(function () { fidx = frames.length - 1; renderFrame(); }); }
  }
];
var stepIdx = 0;

function applyStep(k) {
  stepIdx = Math.max(0, Math.min(demoSteps.length - 1, k));
  var s = demoSteps[stepIdx];
  document.getElementById('demoNarration').innerHTML = '<b>' + s.t + '</b><br>' + s.n;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + demoSteps.length;
  s.run();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ───────────────────────── init ───────────────────────── */
loadSample('sample');
applyStep(0);
window.__markRendered();
